mapper.select:
SELECT sc.id, sc.student_id, sc.class_id, sc.join_time, u.username as student_username, u.nickname as student_nickname, u.real_name as student_real_name, u.email as student_email, c.name as class_name, c.description as class_description, c.created_time as class_created_time FROM student_classes sc LEFT JOIN users u ON sc.student_id = u.id AND u.deleted = 0 LEFT JOIN classes c ON sc.class_id = c.id AND c.deleted = 0 WHERE 1=1
AND sc.class_id = #{classId}
AND sc.student_id = #{studentId}
AND (u.username LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') OR u.real_name LIKE CONCAT('%', #{keyword}, '%') OR c.name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY sc.join_time DESC
